mapper.select:
SELECT id,symbol,business_date,evidence_json,evidence_hash,created_at FROM (
SELECT a.*,ROW_NUMBER() OVER(PARTITION BY business_date,JSON_UNQUOTE(JSON_EXTRACT(evidence_json,'$.priceSource')) ORDER BY id DESC) AS rank_no
FROM corporate_action a WHERE symbol=#{symbol} AND business_date <= #{asOf}
) ranked WHERE rank_no=1 ORDER BY business_date

SELECT id,symbol,business_date,evidence_json,evidence_hash,created_at
FROM investment_thesis
WHERE symbol=#{symbol}
  AND business_date <= #{asOf}
  AND created_at <= TIMESTAMP(#{asOf}, '16:10:00')
ORDER BY business_date DESC,id DESC LIMIT 1
